const tickers = $input.item.json.tickers || [];
const candidates = tickers.filter(t => {
  const price = t.day?.c || 0;
  const volume = t.day?.v || 0;
  return price >= 5 && volume >= 500000;
}).slice(0, 40);
return candidates.map(t => ({
  json: {
    ticker: t.ticker,
    close: t.day?.c,
    open: t.day?.o,
    high: t.day?.h,
    low: t.day?.l,
    volume: t.day?.v,
    prevClose: t.prevDay?.c,
    change_pct: t.todaysChangePerc
  }
}));

const base = $('Pre-Filter Candidates').item.json;
const results = $input.item.json.results || [];
if (results.length < 30) {
  return { json: { ticker: base.ticker, sufficient_data: false } };
}
const allBars = results.slice().reverse();
const bars = allBars.filter(b =>
  b != null &&
  typeof b.o === 'number' &&
  typeof b.h === 'number' &&
  typeof b.l === 'number' &&
  typeof b.c === 'number' &&
  typeof b.v === 'number'
);
if (bars.length < 30) {
  return { json: { ticker: base.ticker, sufficient_data: false } };
}
const n = bars.length;
const mean = arr => arr.reduce((a, b) => a + b, 0) / arr.length;
const fp = (v, d) => v != null && isFinite(v) ? parseFloat(v.toFixed(d)) : null;
function calcEMASeries(closes, period, count) {
  if (closes.length < 2) return [];
  const k = 2 / (period + 1);
  const seedLen = Math.min(period, closes.length);
  let ema = mean(closes.slice(0, seedLen));
  const series = [];
  for (let i = seedLen; i < closes.length; i++) {
    ema = closes[i] * k + ema * (1 - k);
    if (i >= closes.length - count) series.push(ema);
  }
  if (series.length === 0) series.push(ema);
  return series;
}
function calcRSISeries(closes, period, count) {
  const series = [];
  for (let end = closes.length - count; end <= closes.length - 1; end++) {
    const slice = closes.slice(Math.max(0, end - period * 2), end + 1);
    let gains = 0, losses = 0;
    for (let i = 1; i <= period && i < slice.length; i++) {
      const diff = slice[slice.length - i] - slice[slice.length - i - 1];
      if (diff > 0) gains += diff; else losses -= diff;
    }
    const avgGain = gains / period;
    const avgLoss = losses / period;
    const rs = avgLoss === 0 ? 100 : avgGain / avgLoss;
    series.push(fp(100 - 100 / (1 + rs), 2));
  }
  return series;
}
function calcMACDSeries(closes, fast, slow, signal, count) {
  if (closes.length < slow + signal) return [];
  const kFast = 2 / (fast + 1);
  const kSlow = 2 / (slow + 1);
  let ef = mean(closes.slice(0, fast));
  let es = mean(closes.slice(0, slow));
  const macdLines = [];
  for (let i = 0; i < closes.length; i++) {
    if (i >= fast) ef = closes[i] * kFast + ef * (1 - kFast);
    if (i >= slow) {
      es = closes[i] * kSlow + es * (1 - kSlow);
      macdLines.push(ef - es);
    }
  }
  if (macdLines.length < signal) return [];
  const kSig = 2 / (signal + 1);
  let sigEMA = mean(macdLines.slice(0, signal));
  const sigSeries = [];
  for (let i = signal; i < macdLines.length; i++) {
    sigEMA = macdLines[i] * kSig + sigEMA * (1 - kSig);
    if (i >= macdLines.length - count) sigSeries.push(sigEMA);
  }
  const macdTail = macdLines.slice(-count);
  return macdTail.map((m, i) => ({
    line: fp(m, 4),
    signal: fp(sigSeries[i] || 0, 4),
    histogram: fp(m - (sigSeries[i] || 0), 4)
  }));
}
function calcBBSeries(closes, period, mult, count) {
  const series = [];
  for (let i = closes.length - count; i < closes.length; i++) {
    if (i - period + 1 < 0) continue;
    const slice = closes.slice(i - period + 1, i + 1);
    const mid = mean(slice);
    const std = Math.sqrt(mean(slice.map(c => Math.pow(c - mid, 2))));
    const upper = mid + mult * std;
    const lower = mid - mult * std;
    const denom = upper - lower;
    const width = mid > 0 ? (upper - lower) / mid : 0;
    const pctB = denom !== 0 ? (closes[i] - lower) / denom : 0.5;
    series.push({
      upper: fp(upper, 4),
      mid: fp(mid, 4),
      lower: fp(lower, 4),
      width: fp(width, 6),
      pct_b: fp(pctB, 4)
    });
  }
  return series;
}
function calcATR(bars, period) {
  if (bars.length < 2) return 0;
  const trs = bars.slice(1).map((b, i) => {
    const prev = bars[i];
    return Math.max(
      (b.h || 0) - (b.l || 0),
      Math.abs((b.h || 0) - (prev.c || 0)),
      Math.abs((b.l || 0) - (prev.c || 0))
    );
  });
  return fp(mean(trs.slice(-period)), 4);
}
const closes = bars.map(b => b.c);
const COUNT = 6;
const ema200Series = calcEMASeries(closes, 200, 12);
if (ema200Series.length < 1) {
  return { json: { ticker: base.ticker, sufficient_data: false } };
}
const ema200 = ema200Series[ema200Series.length - 1];
const ema200_10ago = ema200Series[Math.max(0, ema200Series.length - 11)];
const rsiSeries = calcRSISeries(closes, 14, COUNT);
const macdSeries = calcMACDSeries(closes, 12, 26, 9, COUNT);
const bbSeries = calcBBSeries(closes, 20, 2, COUNT);
const atr = calcATR(bars.slice(-16), 14);
if (!macdSeries.length || !bbSeries.length || !rsiSeries.length) {
  return { json: { ticker: base.ticker, sufficient_data: false } };
}
const today = bars[n - 1];
const bb = bbSeries[bbSeries.length - 1];
const macd = macdSeries[macdSeries.length - 1];
const rsi = rsiSeries[rsiSeries.length - 1];
const volumes = bars.map(b => b.v || 0);
const volSlice = volumes.slice(-21, -1);
const volume_sma_20 = volSlice.length > 0 ? fp(mean(volSlice), 0) : 1;
const volume_vs_avg = fp((today.v || 0) / (volume_sma_20 || 1), 2);
const bb_width_20bar_min = fp(Math.min(...bbSeries.slice(-20).map(b => b.width || 0)), 6);
const closes50 = closes.slice(-52, -2);
const prior_50bar_high = closes50.length > 0 ? fp(Math.max(...closes50), 4) : fp(today.c, 4);
const closes20 = closes.slice(-22, -2);
const prior_20bar_low = closes20.length > 0 ? fp(Math.min(...closes20), 4) : fp(today.c, 4);
const highs20 = bars.slice(-22, -1).map(b => b.h || 0);
const high_20bar_max = highs20.length > 0 ? fp(Math.max(...highs20), 4) : fp(today.h, 4);
const recentHighs = closes.slice(-12);
const localHighIdx = recentHighs.reduce((maxI, c, i) => c > recentHighs[maxI] ? i : maxI, 0);
const bars_since_local_high = recentHighs.length - 1 - localHighIdx;
const lows3 = bars.slice(-3).map(b => b.l || Infinity);
const low_3bar = fp(Math.min(...lows3), 4);
const lows5 = bars.slice(-5).map(b => b.l || Infinity);
const low_5bar = fp(Math.min(...lows5), 4);
const macd_hist_last5 = macdSeries.slice(-5).map(m => m.histogram);
const macd_line_last5 = macdSeries.slice(-5).map(m => m.line);
const rsi_last5 = rsiSeries.slice(-5);
const volume_last5 = volumes.slice(-5);
const close_last5 = closes.slice(-5).map(c => fp(c, 4));
const low_last5 = bars.slice(-5).map(b => fp(b.l, 4));
const bb_pct_b_last3 = bbSeries.slice(-3).map(b => b.pct_b);
return {
  json: {
    sufficient_data: true,
    ticker: base.ticker,
    signal_date: new Date().toISOString().split('T')[0],
    close: fp(today.c, 4),
    open: fp(today.o, 4),
    high: fp(today.h, 4),
    low: fp(today.l, 4),
    volume_today: today.v || 0,
    rsi_14: rsi,
    macd_line: macd.line,
    macd_signal: macd.signal,
    macd_histogram: macd.histogram,
    bb_upper: bb.upper,
    bb_mid: bb.mid,
    bb_lower: bb.lower,
    bb_width: bb.width,
    bb_pct_b: bb.pct_b,
    bb_width_20bar_min: bb_width_20bar_min,
    ema_200: fp(ema200, 4),
    ema_200_10ago: fp(ema200_10ago, 4),
    atr_14: atr,
    volume_sma_20: volume_sma_20,
    volume_vs_avg: volume_vs_avg,
    low_3bar: low_3bar,
    low_5bar: low_5bar,
    prior_50bar_high: prior_50bar_high,
    prior_20bar_low: prior_20bar_low,
    high_20bar_max: high_20bar_max,
    bars_since_local_high: bars_since_local_high,
    macd_hist_last5: macd_hist_last5,
    macd_line_last5: macd_line_last5,
    rsi_last5: rsi_last5,
    volume_last5: volume_last5,
    close_last5: close_last5,
    low_last5: low_last5,
    bb_pct_b_last3: bb_pct_b_last3
  }
};

const raw = $input.item.json.content?.[0]?.text || '';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  return { json: { qualifies: false, error: 'parse_failed', ticker: 'unknown', raw: raw.slice(0, 200) } };
}
const indicators = $('Compute Indicators').item.json;
parsed._indicators = indicators;
return { json: parsed };
